export interface RawQuestion {
  q: string;
  o: string[];
  a: number;
  e?: string;
}

export const convertToQuizSet = (setId: number, title: string, data: RawQuestion[]) => {
  return {
    id: "set-" + setId,
    title: title,
    questions: data.map((item, idx) => ({
      id: "q-" + setId + "-" + idx,
      text: item.q,
      options: item.o,
      correctAnswer: item.a,
      explanation: item.e || ("Correct Answer: " + item.o[item.a] + ".")
    }))
  };
};

// -- HELPER to create topics easily --
export const createTopic = (id: string, title: string, category: 'Paper I' | 'Paper II' | 'Paper III' | 'Paper IV' | 'PYQ' | 'Current Affairs', setIds: number[] = [], subCategory?: string) => {
  const sets = setIds.map(setId => {
    const data = ALL_SETS_DATA[setId];
    return data ? convertToQuizSet(setId, "Practice Set " + setId, data) : null;
  }).filter(s => s !== null) as QuizSet[];

  // If no real sets, pass empty array. UI will handle "Coming Soon" or empty state

  return {
    id,
    title,
    category,
    subCategory,
    sets
  };
};

